CREATE TABLE IF NOT EXISTS "users" (
	"user_id" BIGINT NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"lastname" VARCHAR(255) NOT NULL,
	"email" VARCHAR(255) NOT NULL UNIQUE,
	"password_hash" TEXT NOT NULL,
	"state" BOOLEAN NOT NULL,
	"date_created" TIMESTAMP NOT NULL,
	"last_access" TIMESTAMP NOT NULL,
	PRIMARY KEY("user_id")
);

CREATE TABLE IF NOT EXISTS "role" (
	"role_id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"description" VARCHAR(255) NOT NULL,
	PRIMARY KEY("role_id")
);

CREATE TABLE IF NOT EXISTS "users_roles" (
	"role_id" BIGINT NOT NULL UNIQUE,
	"user_id" BIGINT NOT NULL UNIQUE,
	PRIMARY KEY("role_id", "user_id")
);

CREATE TABLE IF NOT EXISTS "projects" (
	"project_id" BIGINT NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"description" TEXT NOT NULL,
	"state" VARCHAR(255) NOT NULL,
	"owner_id" BIGINT NOT NULL,
	"date_created" TIMESTAMP NOT NULL,
	PRIMARY KEY("project_id")
);

CREATE TABLE IF NOT EXISTS "project_users" (
	"id" BIGINT NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"project_id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"rol" VARCHAR(255) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "categories" (
	"categories_id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"color" VARCHAR(255) NOT NULL,
	"project_id" BIGINT NOT NULL,
	PRIMARY KEY("categories_id")
);

CREATE TABLE IF NOT EXISTS "tags" (
	"tag_id" BIGINT NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"color" VARCHAR(255) NOT NULL,
	"project_id" BIGINT NOT NULL,
	PRIMARY KEY("tag_id")
);

CREATE TABLE IF NOT EXISTS "task" (
	"task_id" BIGINT NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"title" VARCHAR(255) NOT NULL,
	"description" TEXT NOT NULL,
	"init_date" TIMESTAMP NOT NULL,
	"end_date" TIMESTAMP NOT NULL,
	"state" VARCHAR(255) NOT NULL,
	"project_id" BIGINT NOT NULL,
	"categories_id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"date_created" TIMESTAMP NOT NULL,
	"date_update" TIMESTAMP NOT NULL,
	PRIMARY KEY("task_id")
);

CREATE TABLE IF NOT EXISTS "subtasks" (
	"subtask_id" BIGINT NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"task_id" BIGINT NOT NULL,
	"title" VARCHAR(255) NOT NULL,
	"state" VARCHAR(255) NOT NULL,
	PRIMARY KEY("subtask_id")
);

CREATE TABLE IF NOT EXISTS "task_tags" (
	"task_id" BIGINT NOT NULL,
	"tag_id" BIGINT NOT NULL,
	PRIMARY KEY("task_id", "tag_id")
);

CREATE TABLE IF NOT EXISTS "comments" (
	"comment_id" BIGINT NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"content" TEXT NOT NULL,
	"task_id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"date_created" TIMESTAMP NOT NULL,
	PRIMARY KEY("comment_id")
);

